+import { expect, test } from "bun:test";
+import { runPool } from "./pool";
+
+const flush = () => new Promise((r) => setImmediate(r));
+
+function deferred<T>() {
+  let resolve!: (v: T) => void;
+  let reject!: (e: unknown) => void;
+  const promise = new Promise<T>((res, rej) => {
+    resolve = res;
+    reject = rej;
+  });
+  return { promise, resolve, reject };
+}
+
+test("rule 1: invalid limit and retries are refused before any task runs", async () => {
+  for (const limit of [0, -1, 1.5, NaN]) {
+    let calls = 0;
+    await expect(runPool([() => (calls++, Promise.resolve(1))], limit)).rejects.toBeInstanceOf(RangeError);
+    expect(calls).toBe(0);
+  }
+  for (const retries of [-1, 1.5, NaN, Infinity]) {
+    let calls = 0;
+    await expect(runPool([() => (calls++, Promise.resolve(1))], 1, { retries })).rejects.toBeInstanceOf(RangeError);
+    expect(calls).toBe(0);
+  }
+});
+
+test("rule 1: the RangeError message names the rule that was broken", async () => {
+  await expect(runPool([], 1.5)).rejects.toThrow("limit must be a whole number of 1 or more, or Infinity, got 1.5");
+  await expect(runPool([], NaN)).rejects.toThrow("limit must be a whole number of 1 or more, or Infinity, got NaN");
+  await expect(runPool([], 1, { retries: 1.5 })).rejects.toThrow("retries must be a whole number of 0 or more, got 1.5");
+  await expect(runPool([], 1, { retries: Infinity })).rejects.toThrow("retries must be a whole number of 0 or more, got Infinity");
+});
+
+test("rule 1: limit Infinity starts everything at once", async () => {
+  const ds = [0, 1, 2, 3].map(() => deferred<number>());
