+  let data: string[] = [];
+  let failed = false;
+
+  const handle = (raw: string): SseMessage | undefined => {
+    const line = raw.endsWith('\r') ? raw.slice(0, -1) : raw;
+    if (line === '') {
+      if (data.length === 0) {
+        event = undefined;
+        return undefined;
+      }
+      const msg = event === undefined ? { data: data.join('\n') } : { event, data: data.join('\n') };
+      event = undefined;
+      data = [];
+      return msg;
+    }
+    if (line.startsWith(':')) return undefined;
+    const i = line.indexOf(':');
+    const field = i < 0 ? line : line.slice(0, i);
+    let value = i < 0 ? '' : line.slice(i + 1);
+    if (value.startsWith(' ')) value = value.slice(1);
+    if (field === 'event') event = value;
+    else if (field === 'data') data.push(value);
+    return undefined;
+  };
+
+  try {
+    for (;;) {
+      const { done, value } = await reader.read().catch((err) => {
+        failed = true;
+        throw err;
+      });
+      if (done) break;
+      let text = decoder.decode(value, { stream: true });
+      let n: number;
+      while ((n = text.indexOf('\n')) >= 0) {
+        const msg = handle(buf + text.slice(0, n));
+        buf = '';
+        text = text.slice(n + 1);
+        if (msg) yield msg;
+      }
+      buf += text;
+    }
+    buf += decoder.decode();
+    if (buf !== '') handle(buf);
+    const msg = handle('');
+    if (msg) yield msg;
+  } finally {
+    // Cancel unless a read failed: the stream is then already errored and cancel() would reject, replacing the
+    // error being thrown.
+    try {
+      if (!failed) await reader.cancel();
+    } finally {
+      reader.releaseLock();
+    }
+  }
 }

